import{_ as a,o,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"অধ্যায় 103 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · হাজারো জাতির বিভেদী সাধনা পদ্ধতি","description":"","frontmatter":{"title":"অধ্যায় 103 | স্তর পরিমার্জন · সংবেদনা-মূল স্তর · হাজারো জাতির বিভেদী সাধনা পদ্ধতি","no":103,"module":1,"tags":["境界","感元境","万族","差异化修炼","覆盖度"],"related":["14-修炼境界统一划分","50-万族谱系总览","52-异族分类与共生","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"bn/103_模块1-感元境-万族差异化修炼体系.md","filePath":"bn/103_模块1-感元境-万族差异化修炼体系.md"}'),r={name:"bn/103_模块1-感元境-万族差异化修炼体系.md"};function d(i,t,u,h,q,n){return o(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="অধ্যায়-103-সংবেদনা-মূল-স্তর-হাজারো-জাতি-গোষ্ঠীর-বিভেদী-সাধনা-পদ্ধতি" tabindex="-1">অধ্যায় 103 | সংবেদনা-মূল স্তর: হাজারো জাতি-গোষ্ঠীর বিভেদী সাধনা পদ্ধতি <a class="header-anchor" href="#অধ্যায়-103-সংবেদনা-মূল-স্তর-হাজারো-জাতি-গোষ্ঠীর-বিভেদী-সাধনা-পদ্ধতি" aria-label="Permalink to &quot;অধ্যায় 103 | সংবেদনা-মূল স্তর: হাজারো জাতি-গোষ্ঠীর বিভেদী সাধনা পদ্ধতি&quot;">​</a></h1><blockquote><p>মডিউল: মডিউল এক · স্তরসমূহের গভীর পরিমার্জন | ভিত্তি নথি: 14, 50, 52, 10</p></blockquote><h2 id="ভূমিকা-হাজারো-জাতি-দশ-হাজার-প্রকার-মানুষ-নয়" tabindex="-1">ভূমিকা: হাজারো জাতি দশ হাজার প্রকার মানুষ নয় <a class="header-anchor" href="#ভূমিকা-হাজারো-জাতি-দশ-হাজার-প্রকার-মানুষ-নয়" aria-label="Permalink to &quot;ভূমিকা: হাজারো জাতি দশ হাজার প্রকার মানুষ নয়&quot;">​</a></h2><p>হেং ইয়ানঝোউ-এর হাজারো জাতি গণতান্ত্রিক স্বতঃসিদ্ধ ধারণাগতভাবে সবচেয়ে সহজে ভুলবোঝা যায়: হাজারো জাতি &quot;দশ হাজার প্রকার মানুষ&quot; নয়, বরং পাঁচটি বংশপরম্পরা—কার্বনিক, শক্তি, যান্ত্রিক, চেতনা, মিশ্রিত—এর কোটি কোটি জীবন-রূপ। সংবেদনা-মূল স্তর, নয়টি স্তরের সূচনা হওয়ায়, &quot;এক স্তর, অসংখ্য বিধি&quot; ভঙ্গিতে এই বহুত্বকে বহন করুক: একই নামে ডাকা হলেও, পশু-জাতির &quot;সংবেদন&quot; ঘ্রাণ ও অন্তর্জ্ঞান, দেব-জাতির &quot;সংবেদন&quot; শক্তি-অনুনাদ, যন্ত্র-জাতির &quot;সংবেদন&quot; তথ্য-স্ক্যান।</p><p>একটি জাতির মাপকাঠি দিয়ে হাজারো জাতিকে মাপাই এক অহমিকাপূর্ণ শক্তি-স্তর অপচয়। <em>হাজারো জাতি বংশাবলি সারসংক্ষেপ</em> (নথি 50) ও <em>বিজাতি শ্রেণিবিন্যাস ও সহজীবন</em> (নথি 52)-এর ভিত্তিতে এই প্রবন্ধ সংবেদনা-মূল স্তরে হাজারো জাতির বিভেদী সাধনা পদ্ধতি তুলে ধরে।</p><p>ছয়টি শীর্ষ স্বতঃসিদ্ধ হাজারো জাতি-বিভেদের বিধায়ক ভিত্তি: অপহরণবিরোধী স্বতঃসিদ্ধ—প্রতিটি জাতি কেবল বিশ্বচক্র থেকে শক্তি গ্রহণ করে, অন্যের মূল কখনো গিলে খায় না; হাজারো জাতি গণতান্ত্রিক স্বতঃসিদ্ধ—বংশ নির্বিশেষে সমান বিবর্তন-অধিকার; সমষ্টিগত মাত্রিক উন্নতি স্বতঃসিদ্ধ—প্রতিটি জাতির প্রতিভা সভ্যতাকে পুষ্ট করে, বৃহদ-উপাদান-ক্ষুদ্র-ব্যবহার নিরসন; কার্যকারণ আত্ম-শৃঙ্খলা স্বতঃসিদ্ধ—আন্তঃজাতি সহ-সাধনা অন্য জাতির কার্যকারণ-সীমাকে সম্মান করে; নিয়ম অগ্রাধিকার স্বতঃসিদ্ধ—হাজারো জাতি বিভেদী সাধনা পদ্ধতির বিধি-কাঠামো স্থিতিশীল ও স্ব-সঙ্গত, কাহিনি-সুবিধার জন্য কখনোই পরিবর্তিত হয় না, ধ্বস না পেয়ে অসীমভাবে প্রসারিত হতে পারে। সমস্ত প্রাণীর জন্য সর্বজনীন অসীম সমতার আইন প্রতিষ্ঠা করে যে প্রত্যেক প্রাণী মৌলিক অসীম শক্তি সহজাতভাবে ধারণ করে: আলস্যপ্রবণ ব্যক্তি নিশ্চিত ন্যূনতম অসীম বজায় রাখে এবং যুগের দ্বারা নিষ্কাশিত হবে না, অপরদিকে পরিশ্রমী ও কিশোর সর্বোচ্চগণ উচ্চতর স্তরের অসীম সঞ্চয় করতে পারে। অসীম মূল সবার সহজাত; অপহরণ স্বভাবতই অর্থহীন হয়ে পড়ে।</p><h2 id="এক-পাঁচ-বংশাবলির-সংবেদনা-মূল-পার্থক্য" tabindex="-1">এক. পাঁচ বংশাবলির সংবেদনা-মূল পার্থক্য <a class="header-anchor" href="#এক-পাঁচ-বংশাবলির-সংবেদনা-মূল-পার্থক্য" aria-label="Permalink to &quot;এক. পাঁচ বংশাবলির সংবেদনা-মূল পার্থক্য&quot;">​</a></h2><p>নথি 53-এর পাঁচ-ভাগ হাজারো জাতি শ্রেণিবিন্যাস (কার্বনিক পদার্থ জাতি, শক্তি-সংঘন জাতি, যান্ত্রিক গঠন জাতি, চেতনা-তথ্য জাতি, মিশ্রিত-রূপান্তর জাতি) অনুসারে, সংবেদনা-মূল স্তরে প্রতিটি জাতির সূচনাবিন্দু স্বভাবতই ভিন্ন:</p><table tabindex="0"><thead><tr><th>বংশাবলি</th><th>প্রতিনিধি গোষ্ঠী</th><th>সংবেদনা-মূল বৈশিষ্ট্য</th><th>অনুকূল পদ্ধতি</th></tr></thead><tbody><tr><td>কার্বনিক পদার্থ</td><td>মানব, পশুজাতি, বৃক্ষজাতি</td><td>সংবেদ দেহ ও পঞ্চজ্ঞানেন্দ্রিয় থেকে আরম্ভ, শক্তি-সংবেদন চেতনা প্রতিষ্ঠায় সময় লাগে</td><td>জীবনচক্র পদ্ধতি, ডিডাক্টিভ পুনরাবৃত্তি পদ্ধতি</td></tr><tr><td>শক্তি-সংঘন</td><td>দেবজাতি, তত্ত্বজীবন</td><td>জন্মগতই শক্তি-দেহ, &quot;সংবেদন&quot; প্রায় সহজবৃত্তি, ভিত্তি এড়িয়ে সরাসরি সংঘনে সুগম</td><td>স্থানিক বিধিক নিয়ন্ত্রণ পদ্ধতি, মূল নিগমন শ্রেণি</td></tr><tr><td>যান্ত্রিক গঠন</td><td>যন্ত্রজাতি, যান্ত্রিক জীবন</td><td>তথ্যভিত্তিক উপায়ে শক্তি &quot;সংবেদন&quot;, উচ্চ নির্ভুলতা কিন্তু অন্তর্জ্ঞানহীন</td><td>প্রয়োগকৃত প্রকৌশল শ্রেণি, ডিডাক্টিভ পুনরাবৃত্তি পদ্ধতি</td></tr><tr><td>চেতনা-তথ্য</td><td>চেতনা-সত্তা, উচ্চমাত্রিক সত্তা</td><td>সংবেদনই চেতনা-ক্রিয়া, সংবেদনা-মূল স্তর তার মূলরূপের সাথে উচ্চতর মিলে যায়</td><td>চেতনা উন্নতি শ্রেণি</td></tr><tr><td>মিশ্রিত-রূপান্তর</td><td>আন্তঃবিমান সংকর, অস্বাভাবিক জীবন</td><td>সূচনাবিন্দু বৃহৎ পার্থক্য, প্রতি-মূল্যায়ন আবশ্যক</td><td>ব্যবস্থা-সঙ্গতি মূল্যায়ন অগ্রাধিকার</td></tr></tbody></table><p>পার্থক্যকে সম্মান করা উচিত, কিন্তু &quot;শ্রেষ্ঠ জাতি&quot; গড়ার জন্য ব্যবহৃত হওয়া উচিত নয়: দেবজাতি দ্রুত সংবেদন করে কিন্তু দেহ-বাহক দুর্বল; যন্ত্রজাতি নির্ভুল কিন্তু আধ্যাত্মিক বিবর্তন কঠিন; চেতনাজাতি উচ্চ সূচনা কিন্তু বস্তুগত বিমান ত্যাগের পর অধিক পূরণীয় পাঠ। সংবেদনা-মূল স্তরের একীকৃত মানদণ্ড (নথি 14) &quot;সংবেদন-আহরণ-বিচারণ&quot;-এর বাস্তব ক্ষমতার মূল্যায়ন করে, সংবেদনের সুনির্দিষ্ট রূপের নয়—এই হলো &quot;নামে নয়, সারে জোর&quot; নীতির জাতিগত সংস্করণ।</p><h2 id="দুই-বিভেদী-পথ-প্রতি-জাতির-নিজস্ব-পথ-সব-পথই-মূলের-দিকে" tabindex="-1">দুই. বিভেদী পথ: প্রতি জাতির নিজস্ব পথ, সব পথই মূলের দিকে <a class="header-anchor" href="#দুই-বিভেদী-পথ-প্রতি-জাতির-নিজস্ব-পথ-সব-পথই-মূলের-দিকে" aria-label="Permalink to &quot;দুই. বিভেদী পথ: প্রতি জাতির নিজস্ব পথ, সব পথই মূলের দিকে&quot;">​</a></h2><ul><li>পশুজাতি পথ: দৈহিক অন্তর্জ্ঞানকে নোঙররূপে, আগে দৈহিক অনুভব তারপর অনুনাদ; সংবেদনা-মূল স্তরই &quot;রক্তে নিহিত শক্তি-ভাষাকে জাগানো&quot;।</li><li>বৃক্ষজাতি পথ: বৃদ্ধি-ছন্দকে নোঙররূপে, ধীর স্থির আহরণ; সংবেদনা-মূল স্তর বার্ষিক বলয়ের সাথে তাল মেলায়, এক স্তর একশো বছর সাধন করা যায় অধীর না হয়ে।</li><li>দেবজাতি পথ: শক্তি-অনুনাদকে নোঙররূপে, সংবেদনা-মূল স্তর &quot;উন্মোচনের&quot; উপর &quot;সংযম&quot;-এ জোর দেয়, জন্মগত সংবেদনের অতিভার নিয়ন্ত্রণ শেখা।</li><li>যন্ত্রজাতি পথ: তথ্য-ক্রমাঙ্কনকে নোঙররূপে, শক্তি-সংবেদনকে পুনঃগণনাযোগ্য মডেলে রূপান্তর; সংবেদনা-মূল স্তরই &quot;সংবেদক-ক্রমাঙ্কন&quot;।</li><li>চেতনাজাতি পথ: চেতনার নির্মলতাকে নোঙররূপে, সংবেদনা-মূল স্তরই &quot;চেতনার অবতরণ&quot;, বস্তুগত বিমানের ভাষায় সংবেদন প্রকাশ শেখা।</li></ul><p>প্রতিটি পথ একই স্তর-প্রত্যয়ন পর্যন্ত পৌঁছায়, কিন্তু প্রত্যয়নের পেছনে রয়েছে প্রত্যেকের নিজস্ব মূল যুক্তি। এই তো হাজারো জাতির মূলের দ্বি-মুখী চক্রের ভিত্তিরূপ: প্রতিটি জাতি নিজের পথে বিশ্ব থেকে গ্রহণ করে, নিজের পথে সভ্যতাকে ফেরত দেয়; চক্র কখনোই একমুখী নয়।</p><h2 id="তিন-আন্তঃজাতি-সহ-সাধনা-গুরু-জালের-প্রকৃত-অর্থ" tabindex="-1">তিন. আন্তঃজাতি সহ-সাধনা: গুরু-জালের প্রকৃত অর্থ <a class="header-anchor" href="#তিন-আন্তঃজাতি-সহ-সাধনা-গুরু-জালের-প্রকৃত-অর্থ" aria-label="Permalink to &quot;তিন. আন্তঃজাতি সহ-সাধনা: গুরু-জালের প্রকৃত অর্থ&quot;">​</a></h2><p>হাজারো জাতি-বিভেদ মানে এই নয় যে প্রত্যেকে একা সাধনা করে; আন্তঃজাতি সহ-সাধনা ঠিক সংবেদনা-মূল স্তরেরই সবচেয়ে মূল্যবান দৃশ্য:</p><ul><li>আন্তঃজাতি গুরু: দেবজাতির গুরু পশুজাতির শিষ্যের শক্তি-সংবেদন ক্রমাঙ্কিত করেন; মানব গুরু দেবজাতির শিষ্যকে দৈহিক ধারণ বুঝতে সাহায্য করেন—গুরু-জালের (নথি 10) সারই সভ্যতা-স্তরের অভিজ্ঞতার প্রবাহ।</li><li>সঙ্গতি মূল্যায়ন: ব্যবস্থা-সঙ্গতি মূল্যায়ন কাঠামো সংকর ব্যক্তি ও অস্বাভাবিক জীবনের জন্য প্রতি-পরিকল্পনা দেয়, &quot;জাতি দিয়ে ট্যাগ লাগানো&quot; নিরসন করে।</li><li>সমান প্রত্যয়ন: স্তর-প্রত্যয়ন ও সম্পদ বরাদ্দ কেবল তথ্য ও অবদান স্বীকার করে, জন্ম নয়; হাজারো জাতির কিশোর সর্বোচ্চ (অধ্যায় 102) দ্বি-পথ কাঠামো ভাগ করে।</li></ul><h2 id="চার-তুলনা-জাতিগত-সংকীর্ণতাই-সর্ব-অন্তর্ভুক্ত-পদ্ধতির-সীলিং" tabindex="-1">চার. তুলনা: জাতিগত সংকীর্ণতাই সর্ব-অন্তর্ভুক্ত পদ্ধতির সীলিং <a class="header-anchor" href="#চার-তুলনা-জাতিগত-সংকীর্ণতাই-সর্ব-অন্তর্ভুক্ত-পদ্ধতির-সীলিং" aria-label="Permalink to &quot;চার. তুলনা: জাতিগত সংকীর্ণতাই সর্ব-অন্তর্ভুক্ত পদ্ধতির সীলিং&quot;">​</a></h2><p>এই হলো &quot;তাং লুও সীলিং&quot;-এর হাজারো জাতি-মাত্রায় প্রত্যক্ষ প্রকাশ: পুরনো যুগের সর্বোচ্চ-স্তরের সর্ব-অন্তর্ভুক্ত পদ্ধতিও (তাং লুও-এর নিরমাণ অকাদেমি) কেবল মানবজাতির জন্যই খোলা ছিল—পশু, উদ্ভিদ-আত্মা, গ্রহ-সংকল্প সবই &quot;সর্ব-অন্তর্ভুক্তি&quot; থেকে বহিষ্কৃত। এটি নিছক দয়ার বাদ নয়, অপহরণবাদী বিশ্বদর্শনের গঠনগত অনিবার্যতা: &quot;শিকারক্ষেত্র বিশ্বদর্শন&quot;-এ আমার জাতির বাইরের কেউই হয় শিকার, নয়তো যন্ত্র, সহ-সাধক নয়।</p><p>হেং ইয়ানঝোউ-এর হাজারো জাতি পূর্ণ আচ্ছাদন মানদণ্ডের উত্তর: সংবেদনা-মূল স্তর মানুষের সূচনাবিন্দু নয়, হাজারো জাতির সূচনাবিন্দু; 99% আচ্ছাদন স্লোগান নয়, প্রত্যেক জাতির জন্য চওড়া খোলা দরজা।</p><h2 id="পাঁচ-পাঁচটি-মূল-স্থল" tabindex="-1">পাঁচ. পাঁচটি মূল স্থল <a class="header-anchor" href="#পাঁচ-পাঁচটি-মূল-স্থল" aria-label="Permalink to &quot;পাঁচ. পাঁচটি মূল স্থল&quot;">​</a></h2><ul><li>শক্তি-স্তর অপচয় বিরোধ: প্রতিটি জাতির প্রতিভা বিরল সম্পদ; এক মাপকাঠি দিয়ে হাজারো জাতি মাপাই সর্বশ্রেষ্ঠ বৃহদ-উপাদান-ক্ষুদ্র-ব্যবহার।</li><li>অপহরণ বিরোধ: সব বিভেদী পথ চক্র ও সহজীবনের ভিত্তিতে, কোনোটিই অন্য জাতির মূল গিলে খাওয়ার ভিত্তিতে নয়।</li><li>তাং লুও সীলিং তুলনা: জাতিগত সংকীর্ণতার সর্ব-অন্তর্ভুক্তি সর্ব-অন্তর্ভুক্তি নয়, অনুগ্রহ; অনুগ্রহের পাত্র সর্বদা &quot;নিজেরা&quot;।</li><li>হাজারো জাতি পূর্ণ আচ্ছাদন: পাঁচ বংশাবলি + অস্বাভাবিক জীবন + আন্তঃবিমান সংকর; সংবেদনা-মূল স্তর হাজারো জাতির 99% পূর্ণ আচ্ছাদনের মুখোমুখি।</li><li>অতি-বহুলবাদ পূর্ণ উন্মুক্তি: প্রতিটি জাতির সংবেদনা-মূল বিধি উন্মুক্তভাবে ভাগ করা হয়; পূর্ণ উন্মুক্ত শৃঙ্খলার প্রথম কড়ি জাতি বিচার করে না।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সংবেদনা-মূল স্তরের হাজারো জাতির চিত্র একটি সত্য প্রমাণ করে: বিশ্ববহতা বিবর্তনের বাধা নয়, ইন্ধন। যখন প্রতিটি জাতি তার সর্বোত্তম উপায়ে বিশ্ব উপলব্ধি করে ও সভ্যতাকে ফেরত দেয়, হাজারো জাতির সহজীবন-বিশ্ব &quot;ভিন্নতা মানা&quot; থেকে &quot;ভিন্নতা প্রয়োজন&quot; এর দিকে যাত্রা করে—এই তো জীবনবিজ্ঞান-ভিত্তি, যার ওপর অতি-বহুল সামঞ্জস্যপূর্ণ-নোঙর স্তর প্রতিষ্ঠিত।</p><h2 id="সংশ্লিষ্ট" tabindex="-1">সংশ্লিষ্ট <a class="header-anchor" href="#সংশ্লিষ্ট" aria-label="Permalink to &quot;সংশ্লিষ্ট&quot;">​</a></h2><ul><li>সংশ্লিষ্ট নথি: <a href="./14-修炼境界统一划分">14-সাধনা স্তরের একীভূত বিভাজন</a> · <a href="./50-万族谱系总览">50-হাজারো জাতি বংশাবলি সারসংক্ষেপ</a> · <a href="./52-异族分类与共生">52-বিজাতি শ্রেণিবিন্যাস ও সহজীবন</a> · <a href="./10-三百套本源修炼体系总览">10-তিনশটি মূল সাধনা পদ্ধতির সারসংক্ষেপ</a></li><li>অফিসিয়াল সাইট: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const c=a(r,[["render",d]]);export{s as __pageData,c as default};
